namespace sv_de8418c372d74016b33946f8f62e0d24.Models;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_de8418c372d74016b33946f8f62e0d24.Components.Pages.Settings

<nav class="settings-sidebar">
    <h5 class="px-3 py-2 text-muted mb-1">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link w-100 text-start @(section.Key == ActiveSection ? "active" : "")"
                        @onclick="() => OnSectionSelected.InvokeAsync(section.Key)">
                    <span class="me-2">@section.Icon</span>
                    @section.Label
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnSectionSelected { get; set; }

    private record SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] Sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];
}

@namespace sv_de8418c372d74016b33946f8f62e0d24.Components.Pages.Settings
@using sv_de8418c372d74016b33946f8f62e0d24.Models
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-header"><h5 class="mb-0">Profile</h5></div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center py-4"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <div class="row">
                <div class="col-md-8">
                    <div class="mb-3">
                        <label class="form-label">Display Name</label>
                        <input type="text" class="form-control" @bind="_displayName" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Email</label>
                        <input type="email" class="form-control" @bind="_email" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Bio</label>
                        <textarea class="form-control" rows="4" @bind="_bio"></textarea>
                    </div>
                </div>
                <div class="col-md-4 text-center">
                    <div class="mb-3">
                        <label class="form-label">Avatar Preview</label>
                        <div class="border rounded p-2 mb-2" style="min-height:120px;">
                            @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                            {
                                <img src="@_avatarUrl" alt="Avatar" class="img-fluid rounded-circle"
                                     style="max-width:100px;max-height:100px;" />
                            }
                            else
                            {
                                <div class="text-muted py-4">No avatar</div>
                            }
                        </div>
                        <small class="text-muted text-break">@_avatarUrl</small>
                    </div>
                </div>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@_saving">
                    Discard Changes
                </button>
            </div>
        }
    </div>
</div>

@code {
    private bool _loading = true, _saving;
    private string? _message;
    private string _displayName = "", _email = "", _avatarUrl = "", _bio = "";
    private UserProfile? _savedProfile;

    protected override async Task OnInitializedAsync()
    {
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        _loading = true;
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile p)
    {
        _displayName = p.DisplayName;
        _email = p.Email;
        _avatarUrl = p.AvatarUrl;
        _bio = p.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _message = "Profile saved successfully!";
        _saving = false;
    }

    private void Discard()
    {
        if (_savedProfile is not null)
            ApplyProfile(_savedProfile);
        _message = null;
    }
}

@namespace sv_de8418c372d74016b33946f8f62e0d24.Components.Pages.Settings
@using sv_de8418c372d74016b33946f8f62e0d24.Models
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-header"><h5 class="mb-0">Notifications</h5></div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center py-4"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <h6 class="mb-3">Notification Channels</h6>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>

            <div class="form-check form-switch mb-4">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>

            <h6 class="mb-3">Muted Channels</h6>

            @if (_allChannels.Count == 0)
            {
                <p class="text-muted">No channels available.</p>
            }
            else
            {
                <div class="list-group mb-4">
                    @foreach (var channel in _allChannels)
                    {
                        var isMuted = _mutedChannels.Contains(channel);
                        <label class="list-group-item d-flex align-items-center">
                            <input class="form-check-input me-2" type="checkbox"
                                   checked="@isMuted"
                                   @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                            <span>@channel</span>
                            @if (isMuted)
                            {
                                <span class="badge bg-secondary ms-auto">Muted</span>
                            }
                        </label>
                    }
                </div>
            }

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Preferences
            </button>
        }
    </div>
</div>

@code {
    private bool _loading = true, _saving;
    private bool _emailNotifications, _pushNotifications, _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _allChannels = new();
    private string? _message;

    // Channels available in the system; in a real app these would come from a service
    private static readonly List<string> DefaultChannels =
        ["general", "announcements", "engineering", "design", "marketing", "support"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _allChannels = DefaultChannels;
        _loading = false;
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var prefs = new NotificationPrefs(
            _emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _message = "Notification preferences saved!";
        _saving = false;
    }
}

@namespace sv_de8418c372d74016b33946f8f62e0d24.Components.Pages.Settings
@using sv_de8418c372d74016b33946f8f62e0d24.Models
@inject ISettingsService SettingsService

<div class="card mb-3">
    <div class="card-header"><h5 class="mb-0">Security</h5></div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center py-4"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_statusMessage))
            {
                <div class="alert @(_statusIsError ? "alert-danger" : "alert-success") alert-dismissible fade show">
                    @_statusMessage
                    <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
                </div>
            }

            <!-- Change Password Panel -->
            <div class="mb-4">
                <button class="btn btn-outline-secondary w-100 text-start d-flex justify-content-between align-items-center"
                        @onclick="() => _passwordExpanded = !_passwordExpanded">
                    <span>🔑 Change Password</span>
                    <span>@(_passwordExpanded ? "▲" : "▼")</span>
                </button>

                @if (_passwordExpanded)
                {
                    <div class="border rounded-bottom p-3">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-warning" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                            @if (_changingPassword) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="mb-4 p-3 border rounded">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Two-Factor Authentication</h6>
                        <small class="text-muted">
                            @if (_twoFactorEnabled)
                            {
                                <span class="text-success">● Enabled</span>
                            }
                            else
                            {
                                <span class="text-danger">● Disabled</span>
                            }
                        </small>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                    </div>
                </div>
                @if (_settings?.LastPasswordChange is not null)
                {
                    <small class="text-muted d-block mt-2">
                        Last password change: @_settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                    </small>
                }
            </div>

            <!-- Active Sessions -->
            <div>
                <h6 class="mb-3">Active Sessions</h6>
                @if (_settings?.Sessions.Count > 0)
                {
                    <div class="table-responsive">
                        <table class="table table-hover align-middle">
                            <thead class="table-light">
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _settings.Sessions)
                                {
                                    var isCurrent = session == _settings.Sessions.First();
                                    <tr>
                                        <td>
                                            @session.Device
                                            @if (isCurrent) { <span class="badge bg-primary ms-1">Current</span> }
                                        </td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("MMM dd, yyyy h:mm tt")</td>
                                        <td>
                                            @if (!isCurrent)
                                            {
                                                <button class="btn btn-sm btn-outline-danger"
                                                        @onclick="() => PromptRevoke(session)">
                                                    Revoke
                                                </button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
                else
                {
                    <p class="text-muted">No active sessions.</p>
                }
            </div>

            <!-- Revoke Confirmation Dialog -->
            @if (_sessionToRevoke is not null)
            {
                <div class="modal d-block" tabindex="-1" style="background:rgba(0,0,0,0.5);">
                    <div class="modal-dialog modal-dialog-centered">
                        <div class="modal-content">
                            <div class="modal-header">
                                <h5 class="modal-title">Revoke Session</h5>
                                <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                            </div>
                            <div class="modal-body">
                                <p>Are you sure you want to revoke the session on
                                    <strong>@_sessionToRevoke.Device</strong> from
                                    <strong>@_sessionToRevoke.Location</strong>?</p>
                                <p class="text-muted small">This will sign out that device immediately.</p>
                            </div>
                            <div class="modal-footer">
                                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                <button class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@_revoking">
                                    @if (_revoking) { <span class="spinner-border spinner-border-sm me-1"></span> }
                                    Revoke
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            }
        }
    </div>
</div>

@code {
    private bool _loading = true, _changingPassword, _revoking;
    private bool _passwordExpanded, _twoFactorEnabled;
    private string _currentPassword = "", _newPassword = "", _confirmPassword = "";
    private string? _statusMessage;
    private bool _statusIsError;
    private SecuritySettings? _settings;
    private ActiveSession? _sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        _loading = true;
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _statusMessage = "New password cannot be empty.";
            _statusIsError = true;
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _statusMessage = "New password and confirmation do not match.";
            _statusIsError = true;
            return;
        }

        _changingPassword = true;
        _statusIsError = false;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _statusMessage = "Password updated successfully!";
            _currentPassword = _newPassword = _confirmPassword = "";
            _passwordExpanded = false;
        }
        catch (Exception ex)
        {
            _statusMessage = $"Failed to change password: {ex.Message}";
            _statusIsError = true;
        }
        _changingPassword = false;
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _statusMessage = $"Session on {_sessionToRevoke.Device} revoked.";
            _statusIsError = false;
            _sessionToRevoke = null;
            // Reload sessions
            _settings = await SettingsService.GetSecuritySettingsAsync();
        }
        catch (Exception ex)
        {
            _statusMessage = $"Failed to revoke session: {ex.Message}";
            _statusIsError = true;
        }
        _revoking = false;
    }
}

