    private bool _passwordExpanded, _twoFactorEnabled;
    private string _currentPassword = "", _newPassword = "", _confirmPassword = "";
    private string? _statusMessage;
    private bool _statusIsError;
    private SecuritySettings? _settings;
    private ActiveSession? _sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        _loading = true;
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _statusMessage = "New password cannot be empty.";
            _statusIsError = true;
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _statusMessage = "New password and confirmation do not match.";
            _statusIsError = true;
            return;
        }

        _changingPassword = true;
        _statusIsError = false;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _statusMessage = "Password updated successfully!";
            _currentPassword = _newPassword = _confirmPassword = "";
            _passwordExpanded = false;
        }
        catch (Exception ex)
        {
            _statusMessage = $"Failed to change password: {ex.Message}";
            _statusIsError = true;
        }
        _changingPassword = false;
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _statusMessage = $"Session on {_sessionToRevoke.Device} revoked.";
            _statusIsError = false;
            _sessionToRevoke = null;
            // Reload sessions
            _settings = await SettingsService.GetSecuritySettingsAsync();
        }
        catch (Exception ex)
        {
            _statusMessage = $"Failed to revoke session: {ex.Message}";
            _statusIsError = true;
        }
        _revoking = false;
    }
}
"}

{"path": "/tmp/sv-de8418c372d74016b33946f8f62e0d24/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_de8418c372d74016b33946f8f62e0d24.Components.Pages.Settings
@using sv_de8418c372d74016b33946f8f62e0d24.Models
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-header"><h5 class="mb-0">Appearance</h5></div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center py-4"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <div class="row">
                <div class="col-md-6">
                    <!-- Theme -->
                    <div class="mb-4">
                        <h6>Theme</h6>
                        @foreach (var theme in _themes)
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="theme-@theme" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="theme-@theme">@theme</label>
                            </div>
                        }
                    </div>

                    <!-- Font Size -->
                    <div class="mb-4">
                        <h6>Font Size</h6>
                        @foreach (var size in _fontSizes)
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="font-@size" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="font-@size">@size</label>
                            </div>
                        }
                    </div>

                    <!-- Language -->
                    <div class="mb-4">
                        <h6>Language</h6>
                        <select class="form-select" @bind="_language">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang.Key">@lang.Value</option>
                            }
                        </select>
                    </div>

                    <!-- Compact Mode -->
                    <div class="mb-4">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>

                    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Save
                    </button>
                </div>

                <!-- Live Preview -->
                <div class="col-md-6">
                    <h6>Preview</h6>
                    <div class="border rounded @PreviewContainerClass" style="@PreviewContainerStyle">
                        <div class="@PreviewPadding">
                            <div class="d-flex justify-content-between align-items-center mb-2"
                                 style="@PreviewHeaderStyle">
                                <strong style="@PreviewFontStyle">Sample App</strong>
                                <span class="badge @PreviewBadgeClass">@_theme</span>
                            </div>
                            <p class="mb-2" style="@PreviewFontStyle">
                                This is a preview of your selected appearance settings.
                            </p>
                            <div class="d-flex gap-2">
                                <button class="btn btn-sm @PreviewButtonClass" style="@PreviewFontStyle"
                                        disabled>Button</button>
                                <button class="btn btn-sm @PreviewOutlineClass" style="@PreviewFontStyle"
                                        disabled>Secondary</button>
                            </div>
                            <hr />
                            <small style="@PreviewFontStyle">
                                Language: @(_languages.GetValueOrDefault(_language, _language)) ·
                                Compact: @(_compactMode ? "On" : "Off")
                            </small>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    private bool _loading = true, _saving;
    private string _theme = "Light", _fontSize = "Medium", _language = "en";
    private bool _compactMode;
    private string? _message;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語",
        ["zh"] = "中文"
    };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        await SettingsService.SaveAppearanceAsync(
            new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _message = "Appearance settings saved!";
        _saving = false;
    }

    // Preview computed properties
    private bool IsDark => _theme == "Dark";

    private string PreviewContainerClass => IsDark ? "text-light" : "";
    private string PreviewContainerStyle =>
        $"background:{(IsDark ? "#1e1e1e" : "#ffffff")};min-height:200px;transition:all 0.3s ease;";

    private string PreviewPadding => _compactMode ? "p-2" : "p-3";

    private string PreviewHeaderStyle =>
        $"border-bottom:1px solid {(IsDark ? "#444" : "#dee2e6")};padding-bottom:0.5rem;";

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size:0.8rem;",
        "Large" => "font-size:1.2rem;",
        _ => "font-size:1rem;"
    };

    private string PreviewBadgeClass => IsDark ? "bg-light text-dark" : "bg-dark";
    private string PreviewButtonClass => IsDark ? "btn-light" : "btn-primary";
    private string PreviewOutlineClass => IsDark ? "btn-outline-light" : "btn-outline-secondary";
}
"}

